USER_CODE = '# -*- coding: utf-8 -*-\n"""中国象棋小程序\n双击 启动象棋.bat 打开: 显示棋盘, 鼠标点选走棋, 可与电脑对弈, 也可双人演练。\n\n操作:\n  - 点一下自己的棋子选中(绿色圆点 = 可以走到的位置), 再点目标位置落子\n  - 人机对战: 默认你执红先行; 选中"执黑"则电脑先走\n  - 摆棋模式: 从工具条选棋子后点棋盘摆放(可连放), 右键删除, 不选工具时点棋子移动;\n    摆好残局后选先行方, 点"完成摆棋(自动解局)"让电脑双方自动走到分出胜负(解残局),\n    或"完成摆棋(对弈)"从该局面开始下; 缺将/照面等错误会提示, 不合常理的摆法会提醒\n  - "自动解局"按钮: 随时让电脑接手双方走棋(再点一次停止); 发现绝杀时\n    对局记录显示"红胜/黑胜(N回合内)"\n  - 对局记录与局面一一对应: 点击记录中任一步即显示该步之后的局面(选中后也可用\n    ↑/↓键逐步查看), 再点该行/点最后一行/点棋盘回到当前局面\n  - 右键点击记录可编辑: 修改记谱文字 / 从此步继续(删除其后着法) / 退回此步之前\n  - 思考深度 1-50 可调(越大越强越慢); 每一步的得分随搜索逐层实时更新\n  - 按钮: 重新开始 / 悔棋 / 提示(电脑帮你算一步)\n  - 勾选 上下翻转 / 左右翻转 翻转棋盘显示(两个都勾 = 整体旋转, 执黑观棋方便)\n\n引擎: 内置开源强引擎 Pikafish(仙鱼, UCI 协议), 走棋与局面评分都由它计算;\n      引擎文件缺失时自动回退到内置 Python 搜索(深度最多4层)。\n\n规则:\n  将/帅: 九宫内直走一步, 两将不可照面(飞将)\n  士/仕: 九宫内斜走一步\n  象/相: 田字斜走, 不过河, 塞象眼不能走\n  马/馬: 日字走, 蹩马腿不能走\n  车/車: 直线任意步\n  炮/砲: 直线走, 隔一个子吃\n  兵/卒: 过河前只进, 过河后可横走, 不后退\n  无子可走(将死/困毙)判负\n"""\nimport os\nimport queue\nimport re\nimport subprocess\nimport threading\nimport time\nimport tkinter as tk\nfrom tkinter import ttk, messagebox, simpledialog\n\n# ---------- 棋盘与规则 ----------\nCOLS, ROWS = 9, 10\n\nVALUE = {\'K\': 10000, \'R\': 900, \'C\': 450, \'H\': 400, \'E\': 200, \'A\': 200, \'P\': 100}\nRED_CHARS = {\'K\': \'帅\', \'A\': \'仕\', \'E\': \'相\', \'H\': \'马\', \'R\': \'车\', \'C\': \'炮\', \'P\': \'兵\'}\nBLACK_CHARS = {\'K\': \'将\', \'A\': \'士\', \'E\': \'象\', \'H\': \'马\', \'R\': \'车\', \'C\': \'炮\', \'P\': \'卒\'}\n\n\nclass Piece:\n    __slots__ = (\'color\', \'type\')\n\n    def __init__(self, color, typ):\n        self.color = color   # \'r\' 红 / \'b\' 黑\n        self.type = typ      # K A E H R C P\n\n\ndef other(color):\n    return \'b\' if color == \'r\' else \'r\'\n\n\ndef char_of(p):\n    return RED_CHARS[p.type] if p.color == \'r\' else BLACK_CHARS[p.type]\n\n\ndef move_notation(b, mv, color):\n    """把走法写成中文记谱(如 炮二平五、马八进七、前车平五), 用于对局记录显示"""\n    CN = \'一二三四五六七八九\'\n    (fr, fc), (tr, tc) = mv\n    p = b[fr][fc]\n    names = RED_CHARS if color == \'r\' else BLACK_CHARS\n    name = names[p.type]\n\n    def colno(f):   # 本方的列号(从本方右侧数起)\n        return (9 - f) if color == \'r\' else (f + 1)\n\n    # 同类型棋子的区分: 同列用 前/后(放棋子名前), 不同列用起始列号(放棋子名后)\n    same = []\n    for r in range(ROWS):\n        for f in range(COLS):\n            q = b[r][f]\n            if q and (r, f) != (fr, fc) and q.color == color and q.type == p.type:\n                same.append((r, f))\n    prefix = \'\'\n    file_mark = CN[colno(fc) - 1]   # 起始列号总要写出, 否则会缺字(如"炮二退一"写成"炮退一")\n    if same:\n        if any(sf == fc for sf in (f for _r, f in same)):\n            # 同类棋子同列时才用 前/后 区分, 并按规则省略列号; 不同列靠列号本身区分\n            if color == \'r\':\n                others = [r for r, f in same if f == fc]\n                prefix = \'前\' if fr < min(others) else \'后\'\n            else:\n                others = [r for r, f in same if f == fc]\n                prefix = \'前\' if fr > max(others) else \'后\'\n            file_mark = \'\'\n    if fr == tr:\n        verb, num = \'平\', CN[colno(tc) - 1]\n    else:\n        forward = (tr < fr) if color == \'r\' else (tr > fr)\n        verb = \'进\' if forward else \'退\'\n        if p.type in (\'H\', \'E\', \'A\'):\n            num = CN[colno(tc) - 1]\n        else:\n            num = CN[abs(tr - fr) - 1]\n    return prefix + name + file_mark + verb + num\n\n\ndef init_board():\n    b = [[None] * COLS for _ in range(ROWS)]\n    back = [\'R\', \'H\', \'E\', \'A\', \'K\', \'A\', \'E\', \'H\', \'R\']\n    for f, t in enumerate(back):\n        b[0][f] = Piece(\'b\', t)\n        b[9][f] = Piece(\'r\', t)\n    for f in (1, 7):\n        b[2][f] = Piece(\'b\', \'C\')\n        b[7][f] = Piece(\'r\', \'C\')\n    for f in (0, 2, 4, 6, 8):\n        b[3][f] = Piece(\'b\', \'P\')\n        b[6][f] = Piece(\'r\', \'P\')\n    return b\n\n\ndef in_board(r, f):\n    return 0 <= r < ROWS and 0 <= f < COLS\n\n\ndef in_palace(color, r, f):\n    if not in_board(r, f) or not 3 <= f <= 5:\n        return False\n    return r <= 2 if color == \'b\' else r >= 7\n\n\ndef crossed_river(color, r):\n    return r >= 5 if color == \'b\' else r <= 4\n\n\ndef pseudo_moves(b, r, f):\n    """某一棋子的全部走法(未过滤将军规则), 返回 [(tr, tf), ...]"""\n    p = b[r][f]\n    out = []\n    c, t = p.color, p.type\n\n    def add(tr, tf):\n        q = b[tr][tf]\n        if q is None or q.color != c:\n            out.append((tr, tf))\n\n    if t == \'K\':\n        for dr, df in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n            tr, tf = r + dr, f + df\n            if in_palace(c, tr, tf):\n                add(tr, tf)\n    elif t == \'A\':\n        for dr, df in ((1, 1), (1, -1), (-1, 1), (-1, -1)):\n            tr, tf = r + dr, f + df\n            if in_palace(c, tr, tf):\n                add(tr, tf)\n    elif t == \'E\':\n        for dr, df in ((2, 2), (2, -2), (-2, 2), (-2, -2)):\n            tr, tf = r + dr, f + df\n            if in_board(tr, tf) and not crossed_river(c, tr) \\\n                    and b[r + dr // 2][f + df // 2] is None:\n                add(tr, tf)\n    elif t == \'H\':\n        for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1),\n                       (1, 2), (1, -2), (-1, 2), (-1, -2)):\n            tr, tf = r + dr, f + df\n            if not in_board(tr, tf):\n                continue\n            lr, lf = (r + dr // 2, f) if abs(dr) == 2 else (r, f + df // 2)\n            if b[lr][lf] is None:\n                add(tr, tf)\n    elif t == \'R\':\n        for dr, df in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n            tr, tf = r + dr, f + df\n            while in_board(tr, tf):\n                q = b[tr][tf]\n                if q is None:\n                    out.append((tr, tf))\n                else:\n                    if q.color != c:\n                        out.append((tr, tf))\n                    break\n                tr, tf = tr + dr, tf + df\n    elif t == \'C\':\n        for dr, df in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n            tr, tf = r + dr, f + df\n            jumped = False\n            while in_board(tr, tf):\n                q = b[tr][tf]\n                if not jumped:\n                    if q is None:\n                        out.append((tr, tf))\n                    else:\n                        jumped = True\n                else:\n                    if q is not None:\n                        if q.color != c:\n                            out.append((tr, tf))\n                        break\n                tr, tf = tr + dr, tf + df\n    elif t == \'P\':\n        dr = 1 if c == \'b\' else -1\n        tr = r + dr\n        if in_board(tr, f):\n            add(tr, f)\n        if crossed_river(c, r):\n            for tf in (f - 1, f + 1):\n                if in_board(r, tf):\n                    add(r, tf)\n    return out\n\n\ndef find_king(b, color):\n    for r in range(ROWS):\n        for f in range(COLS):\n            p = b[r][f]\n            if p and p.color == color and p.type == \'K\':\n                return r, f\n    return None\n\n\ndef is_attacked(b, r, f, by):\n    """(r,f) 是否被 by 方攻击(含飞将)"""\n    # 兵/卒\n    dr = 1 if by == \'b\' else -1\n    if in_board(r - dr, f):\n        p = b[r - dr][f]\n        if p and p.color == by and p.type == \'P\':\n            return True\n    # 马\n    for dr, df in ((2, 1), (2, -1), (-2, 1), (-2, -1),\n                   (1, 2), (1, -2), (-1, 2), (-1, -2)):\n        tr, tf = r - dr, f - df\n        if not in_board(tr, tf):\n            continue\n        p = b[tr][tf]\n        if p and p.color == by and p.type == \'H\':\n            lr, lf = (tr + dr // 2, tf) if abs(dr) == 2 else (tr, tf + df // 2)\n            if b[lr][lf] is None:\n                return True\n    # 车 / 炮 / 飞将\n    for dr, df in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n        tr, tf = r + dr, f + df\n        first = None\n        while in_board(tr, tf):\n            q = b[tr][tf]\n            if q is not None:\n                first = q\n                break\n            tr, tf = tr + dr, tf + df\n        if first is None:\n            continue\n        if first.color == by and first.type in (\'R\', \'K\'):\n            return True\n        # 炮: 越过第一子找炮\n        tr, tf = tr + dr, tf + df\n        while in_board(tr, tf):\n            q = b[tr][tf]\n            if q is not None:\n                if q.color == by and q.type == \'C\':\n                    return True\n                break\n            tr, tf = tr + dr, tf + df\n    # 将/帅相邻\n    for dr, df in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n        tr, tf = r + dr, f + df\n        if in_board(tr, tf):\n            p = b[tr][tf]\n            if p and p.color == by and p.type == \'K\':\n                return True\n    return False\n\n\ndef is_in_check(b, color):\n    k = find_king(b, color)\n    return k is not None and is_attacked(b, k[0], k[1], other(color))\n\n\ndef legal_moves(b, color):\n    """color 方全部合法走法, 返回 [((fr,fc),(tr,tc)), ...]"""\n    moves = []\n    opp = other(color)\n    for r in range(ROWS):\n        for f in range(COLS):\n            p = b[r][f]\n            if not p or p.color != color:\n                continue\n            for tr, tf in pseudo_moves(b, r, f):\n                captured = b[tr][tf]\n                b[tr][tf] = p\n                b[r][f] = None\n                k = find_king(b, color)\n                ok = k is None or not is_attacked(b, k[0], k[1], opp)\n                b[r][f] = p\n                b[tr][tf] = captured\n                if ok:\n                    moves.append(((r, f), (tr, tf)))\n    return moves\n\n\n# ---------- 电脑对弈(AI): 迭代加深 + alpha-beta + 吃子静态搜索 ----------\nINF = 10 ** 9\nMATE = 10 ** 6\nQDEPTH = 6\n\n\nclass Timeout(Exception):\n    pass\n\n\ndef evaluate(b):\n    """红方为正"""\n    score = 0\n    for r in range(ROWS):\n        for f in range(COLS):\n            p = b[r][f]\n            if not p:\n                continue\n            v = VALUE[p.type]\n            if p.type == \'P\' and crossed_river(p.color, r):\n                v += 100\n            score += v if p.color == \'r\' else -v\n    return score\n\n\ndef order_moves(b, moves):\n    def key(mv):\n        victim = b[mv[1][0]][mv[1][1]]\n        return VALUE[victim.type] if victim else 0\n    return sorted(moves, key=key, reverse=True)\n\n\ndef negamax(b, depth, alpha, beta, color, deadline):\n    if time.time() > deadline:\n        raise Timeout()\n    moves = legal_moves(b, color)\n    if not moves:\n        return -MATE\n    if depth <= 0:\n        return quiescence(b, alpha, beta, color, QDEPTH, deadline)\n    best = -INF\n    for mv in order_moves(b, moves):\n        (fr, fc), (tr, tc) = mv\n        captured = b[tr][tc]\n        b[tr][tc] = b[fr][fc]\n        b[fr][fc] = None\n        try:\n            val = -negamax(b, depth - 1, -beta, -alpha, other(color), deadline)\n        finally:\n            b[fr][fc] = b[tr][tc]\n            b[tr][tc] = captured\n        if val >= beta:\n            return beta\n        if val > best:\n            best = val\n        if val > alpha:\n            alpha = val\n    return best\n\n\ndef quiescence(b, alpha, beta, color, qdepth, deadline):\n    if time.time() > deadline:\n        raise Timeout()\n    moves = legal_moves(b, color)\n    if not moves:\n        return -MATE\n    sign = 1 if color == \'r\' else -1\n    if not is_in_check(b, color):\n        stand = evaluate(b) * sign\n        if stand >= beta:\n            return beta\n        if stand > alpha:\n            alpha = stand\n        moves = [mv for mv in moves if b[mv[1][0]][mv[1][1]] is not None]\n        if not moves:\n            return alpha\n    if qdepth <= 0:\n        return evaluate(b) * sign\n    for mv in order_moves(b, moves):\n        (fr, fc), (tr, tc) = mv\n        captured = b[tr][tc]\n        b[tr][tc] = b[fr][fc]\n        b[fr][fc] = None\n        try:\n            val = -quiescence(b, -beta, -alpha, other(color), qdepth - 1, deadline)\n        finally:\n            b[fr][fc] = b[tr][tc]\n            b[tr][tc] = captured\n        if val >= beta:\n            return beta\n        if val > alpha:\n            alpha = val\n    return alpha\n\n\ndef root_search(b, color, depth, deadline):\n    """搜索到指定深度, 返回 (分数, 走法, 是否完整搜索完)"""\n    moves = order_moves(b, legal_moves(b, color))\n    best, bestmv = -INF, moves[0]\n    alpha = -INF\n    for mv in moves:\n        if time.time() > deadline:\n            return best, bestmv, False\n        (fr, fc), (tr, tc) = mv\n        captured = b[tr][tc]\n        b[tr][tc] = b[fr][fc]\n        b[fr][fc] = None\n        try:\n            val = -negamax(b, depth - 1, -INF, -alpha, other(color), deadline)\n        except Timeout:\n            b[fr][fc] = b[tr][tc]\n            b[tr][tc] = captured\n            return best, bestmv, False\n        b[fr][fc] = b[tr][tc]\n        b[tr][tc] = captured\n        if val > best:\n            best, bestmv = val, mv\n        if best > alpha:\n            alpha = best\n    return best, bestmv, True\n\n\ndef search_depth(b, color, depth, deadline=None):\n    """按指定深度搜索 color 方的最佳走法, 返回 (走法, color视角分数)。\n\n    深度越大想得越深(越强也越慢); 无子可走(被将死/困毙)时返回 (None, -MATE)。"""\n    if deadline is None:\n        deadline = float(\'inf\')\n    moves = legal_moves(b, color)\n    if not moves:\n        return None, -MATE\n    sign = 1 if color == \'r\' else -1\n    if len(moves) == 1:\n        return moves[0], evaluate(b) * sign\n    val, mv, _done = root_search(b, color, depth, deadline)\n    return mv, val\n\n\n# ---------- 强引擎(Pikafish/仙鱼, UCI 协议) ----------\nENGINE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), \'engine\')\nENGINE_EXE = os.path.join(ENGINE_DIR, \'pikafish.exe\')\nNO_WINDOW = 0x08000000\nUCI_FILES = \'abcdefghi\'\nFEN_LETTERS = {\n    \'r\': {\'K\': \'K\', \'A\': \'A\', \'E\': \'B\', \'H\': \'N\', \'R\': \'R\', \'C\': \'C\', \'P\': \'P\'},\n    \'b\': {\'K\': \'k\', \'A\': \'a\', \'E\': \'b\', \'H\': \'n\', \'R\': \'r\', \'C\': \'c\', \'P\': \'p\'},\n}\n\n\ndef board_to_fen(b, turn):\n    """棋盘 → 象棋 FEN(红方大写, 黑方小写, 行从黑方开始)"""\n    rows = []\n    for r in range(ROWS):\n        s = \'\'\n        cnt = 0\n        for f in range(COLS):\n            p = b[r][f]\n            if p is None:\n                cnt += 1\n            else:\n                if cnt:\n                    s += str(cnt)\n                    cnt = 0\n                s += FEN_LETTERS[p.color][p.type]\n        if cnt:\n            s += str(cnt)\n        rows.append(s)\n    return \'/\'.join(rows) + (\' w\' if turn == \'r\' else \' b\') + \' - - 0 1\'\n\n\ndef uci_to_move(ucimove):\n    """\'b2e2\' → ((7,1),(7,4))。UCI 坐标: 列 a-i, 行 0-9(0 为红方底线)"""\n    fr, fc = 9 - int(ucimove[1]), UCI_FILES.index(ucimove[0])\n    tr, tc = 9 - int(ucimove[3]), UCI_FILES.index(ucimove[2])\n    return (fr, fc), (tr, tc)\n\n\nclass Engine:\n    """Pikafish 引擎封装。\n\n    后台进程 + 两个内部线程(读输出 / 串行控制), 搜索结果以事件方式送回主线程:\n      (\'score\', token, depth, cp)   每层实时分数(cp 为走棋方视角)\n      (\'bestmove\', token, uci_move) 搜索完成时的最佳走法\n      (\'engine_down\', None)         引擎不可用\n    token 用于区分新旧搜索: 旧搜索残留事件一律丢弃。"""\n\n    def __init__(self, put_event):\n        self.put_event = put_event\n        self.proc = None\n        self.started = False\n        self.req_q = queue.Queue()\n        self.cur_token = 0\n        self._searching = False\n        self._lock = threading.Lock()\n        self._search_done = threading.Event()\n\n    # ---- 对外接口 ----\n    def analyze(self, fen, depth, token):\n        """中断旧搜索, 对 fen 局面搜索到指定深度"""\n        if not self.ensure_started():\n            return\n        self.req_q.put((\'analyze\', fen, depth, token))\n\n    def stop(self):\n        if self.proc is None:\n            return\n        self.req_q.put((\'stop\',))\n\n    def shutdown(self):\n        if self.proc is None:\n            return\n        self.req_q.put((\'quit\',))\n        try:\n            self.proc.terminate()\n        except Exception:\n            pass\n\n    # ---- 内部 ----\n    def ensure_started(self):\n        if self.started:\n            return self.proc is not None\n        self.started = True\n        try:\n            self.proc = subprocess.Popen(\n                [ENGINE_EXE], cwd=ENGINE_DIR,\n                stdin=subprocess.PIPE, stdout=subprocess.PIPE,\n                text=True, bufsize=1, encoding=\'utf-8\', errors=\'ignore\',\n                creationflags=NO_WINDOW)\n        except Exception:\n            self.proc = None\n            self.put_event((\'engine_down\', None))\n            return False\n        threading.Thread(target=self._reader, daemon=True).start()\n        threading.Thread(target=self._controller, daemon=True).start()\n        return True\n\n    def send(self, cmd):\n        if self.proc and self.proc.stdin:\n            try:\n                self.proc.stdin.write(cmd + \'\\n\')\n                self.proc.stdin.flush()\n            except Exception:\n                pass\n\n    def _controller(self):\n        try:\n            self.send(\'uci\')\n            n = max(1, min(8, os.cpu_count() or 4))\n            self.send(\'setoption name Threads value %d\' % n)\n            self.send(\'setoption name Hash value 256\')\n            self.send(\'isready\')\n        except Exception:\n            pass\n        while True:\n            req = self.req_q.get()\n            if req[0] == \'quit\':\n                self.send(\'quit\')\n                return\n            if req[0] == \'stop\':\n                self._stop_search()\n                continue\n            _, fen, depth, token = req\n            self._stop_search()\n            self.cur_token = token\n            self.send(\'position fen \' + fen)\n            with self._lock:\n                self._searching = True\n            self.send(\'go depth %d\' % depth)\n\n    def _stop_search(self):\n        with self._lock:\n            searching = self._searching\n        if searching:\n            self.send(\'stop\')\n            # 等旧搜索的 bestmove 读完, 避免旧事件串到新搜索上\n            self._search_done.wait(10)\n            self._search_done.clear()\n\n    def _reader(self):\n        for line in self.proc.stdout:\n            line = line.strip()\n            if line.startswith(\'info\') and \' score \' in line:\n                m = re.search(r\' depth (\\d+) .*score (cp|mate) (-?\\d+)\', line)\n                if m:\n                    depth = int(m.group(1))\n                    num = int(m.group(3))\n                    if m.group(2) == \'cp\':\n                        cp = num\n                    else:\n                        cp = (MATE - num * 100) if num > 0 else -(MATE - abs(num) * 100)\n                    self.put_event((\'score\', self.cur_token, depth, cp))\n            elif line.startswith(\'bestmove\'):\n                parts = line.split()\n                if len(parts) >= 2 and parts[1] not in (\'(none)\', \'0000\'):\n                    self.put_event((\'bestmove\', self.cur_token, parts[1]))\n                    with self._lock:\n                        if self._searching:\n                            self._searching = False\n                            self._search_done.set()\n        self.put_event((\'engine_down\', None))\n\n\n# ---------- 界面 ----------\nCELL = 60\nMARGIN = 45\nBOARD_W = MARGIN * 2 + CELL * 8\nBOARD_H = MARGIN * 2 + CELL * 9\nPIECE_R = 26\nLINE = \'#5b3a1e\'\nPIECE_FONT = (\'Microsoft YaHei\', 20, \'bold\')\n\n\nclass XiangqiApp:\n    def __init__(self, root):\n        self.root = root\n        root.title(\'中国象棋 - 演练\')\n        root.resizable(False, False)\n        self.mode_var = tk.IntVar(value=1)   # 1 人机对战 / 2 双人对战\n        self.side_var = tk.IntVar(value=1)   # 1 执红 / 2 执黑\n\n        bar = ttk.Frame(root)\n        bar.pack(fill=\'x\', padx=6, pady=(6, 0))\n        ttk.Button(bar, text=\'重新开始\', command=self.restart).pack(side=\'left\', padx=2)\n        ttk.Button(bar, text=\'悔棋\', command=self.undo).pack(side=\'left\', padx=2)\n        ttk.Button(bar, text=\'提示\', command=self.hint).pack(side=\'left\', padx=2)\n        self.btn_auto = ttk.Button(bar, text=\'自动解局\', command=self.toggle_auto_solve)\n        self.btn_auto.pack(side=\'left\', padx=2)\n        ttk.Separator(bar, orient=\'vertical\').pack(side=\'left\', fill=\'y\', padx=6, pady=2)\n        ttk.Radiobutton(bar, text=\'人机对战\', variable=self.mode_var, value=1,\n                        command=self.on_mode_change).pack(side=\'left\', padx=2)\n        ttk.Radiobutton(bar, text=\'双人对战\', variable=self.mode_var, value=2,\n                        command=self.on_mode_change).pack(side=\'left\', padx=2)\n        ttk.Radiobutton(bar, text=\'摆棋模式\', variable=self.mode_var, value=3,\n                        command=self.on_mode_change).pack(side=\'left\', padx=2)\n        ttk.Separator(bar, orient=\'vertical\').pack(side=\'left\', fill=\'y\', padx=6, pady=2)\n        ttk.Radiobutton(bar, text=\'执红\', variable=self.side_var, value=1,\n                        command=self.restart).pack(side=\'left\', padx=2)\n        ttk.Radiobutton(bar, text=\'执黑\', variable=self.side_var, value=2,\n                        command=self.restart).pack(side=\'left\', padx=2)\n        ttk.Separator(bar, orient=\'vertical\').pack(side=\'left\', fill=\'y\', padx=6, pady=2)\n        ttk.Label(bar, text=\'思考深度:\').pack(side=\'left\')\n        self.depth_var = tk.IntVar(value=20)\n        ttk.Spinbox(bar, from_=1, to=50, width=3, textvariable=self.depth_var,\n                    state=\'readonly\').pack(side=\'left\', padx=2)\n        ttk.Label(bar, text=\'(1-50, 越大越强越慢)\').pack(side=\'left\')\n        ttk.Separator(bar, orient=\'vertical\').pack(side=\'left\', fill=\'y\', padx=6, pady=2)\n        self.flip_ud = tk.BooleanVar(value=False)\n        self.flip_lr = tk.BooleanVar(value=False)\n        ttk.Checkbutton(bar, text=\'上下翻转\', variable=self.flip_ud,\n                        command=self.render).pack(side=\'left\', padx=2)\n        ttk.Checkbutton(bar, text=\'左右翻转\', variable=self.flip_lr,\n                        command=self.render).pack(side=\'left\', padx=2)\n\n        # 摆棋工具条(进入摆棋模式时显示在按钮栏与棋盘之间)\n        self.setup_bar = ttk.Frame(root)\n        tk.Label(self.setup_bar, fg=\'#6a4a12\',\n                 text=\'摆棋: 选一个棋子后点棋盘放置(可连放), 右键删除; 不选工具时点棋子可移动它\')\\\n            .pack(anchor=\'w\')\n        pal = ttk.Frame(self.setup_bar)\n        pal.pack(fill=\'x\', pady=(2, 0))\n        self.palette_btns = {}\n        for color, chars in ((\'r\', RED_CHARS), (\'b\', BLACK_CHARS)):\n            for t, ch in chars.items():\n                btn = tk.Button(pal, text=ch, width=2, font=(\'Microsoft YaHei\', 12, \'bold\'),\n                                fg=(\'#c62828\' if color == \'r\' else \'#1a1a1a\'),\n                                command=lambda c=color, tt=t: self.setup_select_tool((\'p\', c, tt)))\n                btn.pack(side=\'left\', padx=1)\n                self.palette_btns[(\'p\', color, t)] = btn\n            ttk.Separator(pal, orient=\'vertical\').pack(side=\'left\', fill=\'y\', padx=5, pady=2)\n        erase_btn = tk.Button(pal, text=\'删除\', width=4, font=(\'Microsoft YaHei\', 10),\n                              command=lambda: self.setup_select_tool((\'erase\',)))\n        erase_btn.pack(side=\'left\', padx=(2, 6))\n        self.palette_btns[(\'erase\',)] = erase_btn\n        move_btn = tk.Button(pal, text=\'移动\', width=4, font=(\'Microsoft YaHei\', 10),\n                             command=lambda: self.setup_select_tool(None))\n        move_btn.pack(side=\'left\', padx=2)\n        self.palette_btns[None] = move_btn\n        acts = ttk.Frame(self.setup_bar)\n        acts.pack(fill=\'x\', pady=(3, 0))\n        ttk.Label(acts, text=\'先行:\').pack(side=\'left\')\n        self.setup_turn_var = tk.StringVar(value=\'r\')\n        ttk.Radiobutton(acts, text=\'红先\', variable=self.setup_turn_var,\n                        value=\'r\').pack(side=\'left\', padx=2)\n        ttk.Radiobutton(acts, text=\'黑先\', variable=self.setup_turn_var,\n                        value=\'b\').pack(side=\'left\', padx=2)\n        ttk.Separator(acts, orient=\'vertical\').pack(side=\'left\', fill=\'y\', padx=6, pady=2)\n        ttk.Button(acts, text=\'清空棋盘\', command=self.setup_clear).pack(side=\'left\', padx=2)\n        ttk.Button(acts, text=\'标准开局\', command=self.setup_standard).pack(side=\'left\', padx=2)\n        ttk.Separator(acts, orient=\'vertical\').pack(side=\'left\', fill=\'y\', padx=6, pady=2)\n        ttk.Button(acts, text=\'完成摆棋(自动解局)\',\n                   command=lambda: self.finish_setup(True)).pack(side=\'left\', padx=2)\n        ttk.Button(acts, text=\'完成摆棋(对弈)\',\n                   command=lambda: self.finish_setup(False)).pack(side=\'left\', padx=2)\n\n        main = ttk.Frame(root)\n        self.main = main\n        main.pack(fill=\'both\', expand=True, padx=6, pady=4)\n        self.canvas = tk.Canvas(main, width=BOARD_W, height=BOARD_H,\n                                bg=\'#f2e3b8\', highlightthickness=0)\n        self.canvas.pack(side=\'left\')\n        self.canvas.bind(\'<Button-1>\', self.on_click)\n        self.canvas.bind(\'<Button-3>\', self.on_click)   # 摆棋模式右键删子\n\n        # 右侧: 对局记录(每步走法 + 局面得分)\n        side = ttk.Frame(main)\n        side.pack(side=\'left\', fill=\'both\', expand=True, padx=(10, 0))\n        ttk.Label(side, text=\'对局记录(得分: 红优为正)\').pack(anchor=\'w\')\n        self.move_tree = ttk.Treeview(side, columns=(\'n\', \'m\', \'s\'),\n                                      show=\'headings\', height=20)\n        self.move_tree.heading(\'n\', text=\'步\')\n        self.move_tree.heading(\'m\', text=\'走法\')\n        self.move_tree.heading(\'s\', text=\'局面分\')\n        self.move_tree.column(\'n\', width=36, anchor=\'center\', stretch=False)\n        self.move_tree.column(\'m\', width=96, anchor=\'center\', stretch=False)\n        self.move_tree.column(\'s\', width=76, anchor=\'center\', stretch=False)\n        self.move_tree.tag_configure(\'red\', foreground=\'#c62828\')\n        self.move_tree.tag_configure(\'black\', foreground=\'#1565c0\')\n        self.move_tree.tag_configure(\'zero\', foreground=\'#888888\')\n        vsb = ttk.Scrollbar(side, orient=\'vertical\', command=self.move_tree.yview)\n        self.move_tree.configure(yscrollcommand=vsb.set)\n        self.move_tree.pack(side=\'left\', fill=\'both\', expand=True)\n        vsb.pack(side=\'right\', fill=\'y\')\n        # 点击/键盘选择记录行 → 显示对应局面; 右键 → 编辑菜单\n        self.move_tree.bind(\'<Button-1>\', self.on_tree_click)\n        self.move_tree.bind(\'<Button-3>\', self.on_tree_right_click)\n        self.move_tree.bind(\'<<TreeviewSelect>>\', self.on_move_selected)\n\n        self.status = tk.Label(root, text=\'\', font=(\'Microsoft YaHei\', 11), fg=\'#333\')\n        self.status.pack(fill=\'x\', padx=10, pady=(0, 8))\n        # 后台线程(引擎/电脑走棋/评分/提示)的结果经队列送回主线程, 避免跨线程碰 tk\n        self.event_q = queue.Queue()\n        self.engine = Engine(self.event_q.put)\n        self.cur_token = 0        # 当前搜索代号: 旧搜索的事件一律丢弃\n        self.analysis_move_id = None\n        self.engine_depth = 0     # 引擎已到达的深度(实时显示)\n        self.engine_target = 0\n        self.hint_pending = False\n        self.use_engine = os.path.exists(ENGINE_EXE)\n        self.in_setup = False       # 摆棋模式中\n        self.setup_sel = None       # 摆棋工具: None=移动 / (\'erase\',) / (\'p\', 颜色, 类型)\n        self.setup_pick = None      # 移动工具捡起的棋子位置\n        self.auto_both = False      # 自动解局: 电脑替双方走棋\n        self.prev_game_mode = 1     # 进入摆棋前所在的对局模式(1 人机 / 2 双人)\n        self.view_idx = None        # 浏览记录: 正在查看的步下标(None = 当前局面)\n        self._tree_guard = False    # 程序性改选中时屏蔽浏览事件\n        self.restart()\n        root.after(100, self._poll_events)\n\n    def _poll_events(self):\n        try:\n            while True:\n                ev = self.event_q.get_nowait()\n                if ev[0] == \'ai\':\n                    _, mv, val, gid = ev\n                    self._ai_done(mv, val, gid)\n                elif ev[0] == \'score\':\n                    _, token, depth, cp = ev\n                    self._on_engine_score(token, depth, cp)\n                elif ev[0] == \'bestmove\':\n                    _, token, uci_mv = ev\n                    self._on_engine_bestmove(token, uci_mv)\n                elif ev[0] == \'score_py\':\n                    _, mid, gid, gen, score = ev\n                    self._score_done(mid, gid, gen, score)\n                elif ev[0] == \'engine_down\':\n                    self.use_engine = False\n                    self.hint_pending = False\n                    if self.ai_thinking or (self.auto_both and not self.game_over\n                                            and not self.in_setup):\n                        depth = min(int(self.depth_var.get()), 4)\n                        threading.Thread(target=self._ai_worker,\n                                         args=(self.game_id, depth), daemon=True).start()\n                elif ev[0] == \'hint\':\n                    _, mv = ev\n                    self._hint_done(mv)\n        except queue.Empty:\n            pass\n        self.root.after(100, self._poll_events)\n\n    # ---------- 引擎事件 ----------\n    def _on_engine_score(self, token, depth, cp):\n        if token != self.cur_token or self.game_over:\n            return\n        self.engine_depth = depth\n        mid = self.analysis_move_id\n        if mid is None or not self.move_tree.exists(str(mid)):\n            return\n        # 引擎分数是走棋方视角, 换算成红优为正\n        red = cp * (1 if self.turn == \'r\' else -1)\n        self.set_move_score(mid, red)\n\n    def _on_engine_bestmove(self, token, uci_mv):\n        if token != self.cur_token:\n            return\n        try:\n            mv = uci_to_move(uci_mv)\n        except Exception:\n            return\n        if self.hint_pending:\n            self.hint_pending = False\n            self._hint_done(mv)\n            if self.moves:   # 提示结束后继续维护当前局面分\n                self._start_analysis(self.moves[-1][\'id\'])\n            return\n        if (self.auto_both or (self.mode == \'ai\' and self.turn != self.human_color)) \\\n                and not self.game_over and not self.in_setup:\n            if mv in legal_moves(self.board, self.turn):\n                self.ai_thinking = False\n                self.do_move(mv)\n\n    def _start_analysis(self, mid, depth_override=None):\n        """对当前局面启动一次搜索: 得分实时更新到 mid 那一步的行上"""\n        self.cur_token += 1\n        self.analysis_move_id = mid\n        depth = depth_override if depth_override is not None else int(self.depth_var.get())\n        self.engine_target = depth\n        if self.use_engine:\n            self.engine.analyze(board_to_fen(self.board, self.turn), depth, self.cur_token)\n        else:\n            # 回退: 内置 Python 搜索(最多4层)\n            if mid is not None:\n                snap = self.snapshot()\n                side = self.turn\n                threading.Thread(target=self._score_worker,\n                                 args=(mid, self.game_id, self.score_gen,\n                                       snap, side, min(depth, 4)), daemon=True).start()\n\n    # ---------- 状态管理 ----------\n    def restart(self):\n        if getattr(self, \'in_setup\', False):\n            # 摆棋中点"重新开始" = 放弃摆棋, 回到普通开局\n            self.in_setup = False\n            self.setup_bar.pack_forget()\n            self.btn_auto.config(state=\'normal\')\n            self.mode_var.set(self.prev_game_mode)\n        self.game_id = getattr(self, \'game_id\', 0) + 1\n        self.cur_token = getattr(self, \'cur_token\', 0) + 1\n        if getattr(self, \'engine\', None) is not None:\n            self.engine.stop()\n        self.mode = \'ai\' if self.mode_var.get() == 1 else \'pvp\'\n        self.human_color = \'r\' if self.side_var.get() == 1 else \'b\'\n        self.board = init_board()\n        self.turn = \'r\'\n        self.start_snap = self.snapshot()   # 起始局面(摆棋开局时为摆好的局面)\n        self.start_turn = \'r\'\n        self.history = []\n        self.moves = []        # 每步记录: {id, n, notation, score}\n        self.move_seq = 0\n        self.score_gen = getattr(self, \'score_gen\', 0) + 1\n        self.hint_pending = False\n        self.engine_depth = 0\n        self.move_tree.delete(*self.move_tree.get_children())\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        self.last_move = None\n        self.last_check = False\n        self.game_over = False\n        self.result_text = \'\'\n        self.ai_thinking = False\n        self.auto_both = False\n        self.view_idx = None\n        self.btn_auto.config(text=\'自动解局\')\n        self.render()\n        if self.mode == \'ai\' and self.human_color == \'b\':\n            self.start_ai()\n\n    # ---------- 摆棋模式 ----------\n    def on_mode_change(self):\n        if self.mode_var.get() == 3:\n            self.enter_setup()\n        elif self.in_setup:\n            # 从摆棋直接切回对局模式 = 完成摆棋(对弈); 校验不过则留在摆棋\n            if not self.finish_setup(False):\n                self.mode_var.set(3)\n        else:\n            self.prev_game_mode = self.mode_var.get()\n            self.restart()\n\n    def enter_setup(self):\n        self.in_setup = True\n        self.auto_both = False\n        self.ai_thinking = False\n        self.hint_pending = False\n        self.cur_token += 1        # 摆棋期间作废一切残留搜索事件\n        self.score_gen += 1\n        self.engine.stop()\n        self.btn_auto.config(text=\'自动解局\', state=\'disabled\')\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        self.setup_pick = None\n        self.setup_bar.pack(fill=\'x\', padx=6, pady=(4, 0), before=self.main)\n        self._refresh_palette()\n        self.render()\n\n    def setup_select_tool(self, tool):\n        # 再点一次当前工具 = 取消选择, 回到"移动"模式\n        self.setup_sel = None if self.setup_sel == tool else tool\n        self.setup_pick = None\n        self._refresh_palette()\n        self.render()\n\n    def _refresh_palette(self):\n        for key, btn in self.palette_btns.items():\n            btn.config(bg=\'#ffd966\' if key == self.setup_sel else \'#f0f0f0\',\n                       relief=\'sunken\' if key == self.setup_sel else \'raised\')\n\n    def setup_clear(self):\n        self.board = [[None] * COLS for _ in range(ROWS)]\n        self.setup_pick = None\n        self.render()\n\n    def setup_standard(self):\n        self.board = init_board()\n        self.setup_pick = None\n        self.render()\n\n    def setup_click(self, r, f, erase=False):\n        if erase or self.setup_sel == (\'erase\',):\n            self.board[r][f] = None\n            self.setup_pick = None\n        elif self.setup_sel is not None:          # 放置选中的棋子\n            _, color, t = self.setup_sel\n            self.board[r][f] = Piece(color, t)\n        elif self.setup_pick is not None:         # 移动模式: 棋子落到目标点\n            pr, pf = self.setup_pick\n            if (r, f) != (pr, pf):\n                self.board[r][f] = self.board[pr][pf]\n                self.board[pr][pf] = None\n            self.setup_pick = None\n        elif self.board[r][f] is not None:        # 捡起棋子\n            self.setup_pick = (r, f)\n        self.render()\n\n    def validate_setup(self):\n        """校验摆好的局面, 返回 (错误列表, 提醒列表); 错误会阻止开局"""\n        b = self.board\n        errors, warns = [], []\n        kings = {}\n        for color, name, kname in ((\'r\', \'红\', \'帅\'), (\'b\', \'黑\', \'将\')):\n            ks = [(r, f) for r in range(ROWS) for f in range(COLS)\n                  if b[r][f] and b[r][f].color == color and b[r][f].type == \'K\']\n            if not ks:\n                errors.append(\'%s方没有%s\' % (name, kname))\n            elif len(ks) > 1:\n                errors.append(\'%s方有%d个%s\' % (name, len(ks), kname))\n            elif not in_palace(color, *ks[0]):\n                errors.append(\'%s不在九宫内\' % kname)\n            else:\n                kings[color] = ks[0]\n        if len(kings) == 2:\n            (r1, f1), (r2, f2) = kings[\'r\'], kings[\'b\']\n            if f1 == f2:\n                # 红帅行号大于黑将, 中间各行取 min/max 之间\n                lo, hi = min(r1, r2), max(r1, r2)\n                if all(b[r][f1] is None for r in range(lo + 1, hi)):\n                    errors.append(\'双方将/帅同列照面(中间无子)\')\n        turn = self.setup_turn_var.get()\n        if len(kings) == 2 and is_in_check(b, other(turn)):\n            mover, checked = (\'红\', \'黑\') if turn == \'r\' else (\'黑\', \'红\')\n            errors.append(\'%s方正被将军却轮到%s方走, 请改选先行方\' % (checked, mover))\n        # 常理性检查(只提醒不阻止)\n        STD = {\'A\': 2, \'E\': 2, \'H\': 2, \'R\': 2, \'C\': 2, \'P\': 5}\n        for color, name in ((\'r\', \'红\'), (\'b\', \'黑\')):\n            names = RED_CHARS if color == \'r\' else BLACK_CHARS\n            cnt = {}\n            for r in range(ROWS):\n                for f in range(COLS):\n                    p = b[r][f]\n                    if p and p.color == color:\n                        cnt[p.type] = cnt.get(p.type, 0) + 1\n            for t, n in cnt.items():\n                if t != \'K\' and n > STD[t]:\n                    warns.append(\'%s方%s有%d个(标准%d个)\' % (name, names[t], n, STD[t]))\n            for r in range(ROWS):\n                for f in range(COLS):\n                    p = b[r][f]\n                    if not (p and p.color == color):\n                        continue\n                    if p.type == \'A\' and not in_palace(color, r, f):\n                        warns.append(\'%s不在九宫内\' % names[p.type])\n                    elif p.type == \'E\':\n                        ok_row = r in ((5, 7, 9) if color == \'r\' else (0, 2, 4))\n                        ok_par = ((r + f) % 2 == 1) if color == \'r\' else ((r + f) % 2 == 0)\n                        if not (ok_row and ok_par):\n                            warns.append(\'%s不在合法的田字点上\' % names[p.type])\n                    elif p.type == \'P\' and (r >= 7 if color == \'r\' else r <= 2):\n                        warns.append(\'%s在己方底线区(永远走不动)\' % names[p.type])\n        return errors, list(dict.fromkeys(warns))\n\n    def finish_setup(self, auto_solve):\n        """结束摆棋进入对局; auto_solve=True 时电脑自动走双方(解残局)。成功返回 True"""\n        errors, warns = self.validate_setup()\n        if errors:\n            messagebox.showwarning(\'摆棋有误\', \'还不能开始:\\n\' + \'\\n\'.join(errors))\n            return False\n        if warns:\n            msg = \'以下摆法不合常理, 仍要开始吗?\\n\' + \'\\n\'.join(warns[:8]) \\\n                  + (\'\\n...\' if len(warns) > 8 else \'\')\n            if not messagebox.askyesno(\'摆棋提醒\', msg):\n                return False\n        self.in_setup = False\n        self.setup_bar.pack_forget()\n        self.btn_auto.config(state=\'normal\')\n        # 从摆好的局面重开一局(记录/悔棋历史清零)\n        self.game_id += 1\n        self.cur_token += 1\n        self.score_gen += 1\n        self.engine.stop()\n        self.auto_both = bool(auto_solve)\n        self.btn_auto.config(text=\'停止解局\' if self.auto_both else \'自动解局\')\n        self.mode_var.set(self.prev_game_mode)\n        self.mode = \'ai\' if self.prev_game_mode == 1 else \'pvp\'\n        self.human_color = \'r\' if self.side_var.get() == 1 else \'b\'\n        self.turn = self.setup_turn_var.get()\n        self.start_snap = self.snapshot()\n        self.start_turn = self.turn\n        self.history = []\n        self.moves = []\n        self.move_seq = 0\n        self.hint_pending = False\n        self.engine_depth = 0\n        self.engine_target = 0\n        self.move_tree.delete(*self.move_tree.get_children())\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        self.last_move = None\n        self.last_check = False\n        self.game_over = False\n        self.result_text = \'\'\n        self.ai_thinking = False\n        self.setup_pick = None\n        self.render()\n        self.check_game_state()   # 分出胜负/轮到电脑/自动解局都从这里接续\n        return True\n\n    # ---------- 自动解局 ----------\n    def toggle_auto_solve(self):\n        if self.in_setup or self.game_over or self.view_idx is not None:\n            return\n        if self.auto_both:\n            self._stop_solving()\n            # 人机模式下若正轮到电脑, 恢复正常的电脑走棋\n            if self.mode == \'ai\' and self.turn != self.human_color:\n                self.start_ai()\n        else:\n            self.auto_both = True\n            self.btn_auto.config(text=\'停止解局\')\n            if not self.ai_thinking:\n                self.start_ai()\n        self.update_status()\n\n    def _stop_solving(self):\n        self.auto_both = False\n        self.btn_auto.config(text=\'自动解局\')\n        if self.ai_thinking:\n            self.ai_thinking = False\n            self.cur_token += 1   # 丢弃这次思考的残留结果\n            self.engine.stop()\n\n    def _auto_step(self):\n        if self.auto_both and not self.game_over and not self.in_setup and not self.ai_thinking:\n            self.start_ai()\n\n    def snapshot(self):\n        return tuple(tuple(row) for row in self.board)\n\n    def do_move(self, mv, score=None):\n        self.view_idx = None       # 有新的一步, 退出记录浏览\n        notation = move_notation(self.board, mv, self.turn)\n        self.history.append(self.snapshot())\n        (fr, fc), (tr, tc) = mv\n        self.board[tr][tc] = self.board[fr][fc]\n        self.board[fr][fc] = None\n        self.last_move = mv\n        self.turn = other(self.turn)\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        # 记入对局记录\n        self.move_seq += 1\n        mid = self.move_seq\n        self.moves.append({\'id\': mid, \'n\': len(self.moves) + 1,\n                           \'notation\': notation, \'score\': score, \'mv\': mv})\n        self.move_tree.insert(\'\', \'end\', iid=str(mid),\n                              values=(self.moves[-1][\'n\'], notation, \'…\'))\n        self.move_tree.see(str(mid))\n        self._tree_guard = True\n        try:\n            self.move_tree.selection_set(str(mid))\n        finally:\n            self._tree_guard = False\n        if score is not None:\n            self.set_move_score(mid, score)\n        else:\n            # 先立即显示静态估值分(秒出), 再由引擎搜索逐层实时细化\n            self.set_move_score(mid, evaluate(self.board))\n        self.render()\n        self.check_game_state()\n        if not self.game_over and not self.auto_both \\\n                and not (self.mode == \'ai\' and self.turn != self.human_color):\n            # 非终局且不轮到电脑时启动局面评分搜索\n            # (人机模式下轮到电脑时, 电脑的思考搜索本身就是这步的评分, 无需重复;\n            #  自动解局时每步后面紧接电脑思考, 同理不重复)\n            self._start_analysis(mid)\n\n    def _score_worker(self, mid, gid, gen, snap, side, depth):\n        board = [list(row) for row in snap]   # 快照是元组, 搜索需要可变棋盘\n        try:\n            _, val = search_depth(board, side, depth)\n            red_score = val * (1 if side == \'r\' else -1)\n        except Exception:\n            red_score = evaluate(board)       # 搜索异常时退回静态估值\n        self.event_q.put((\'score_py\', mid, gid, gen, red_score))\n\n    def _score_done(self, mid, gid, gen, score):\n        if gid != self.game_id or gen != self.score_gen or self.game_over:\n            return   # 已悔棋/重开/对局已结束时, 迟到的评分不再覆盖\n        if not self.move_tree.exists(str(mid)):\n            return\n        self.set_move_score(mid, score)\n\n    def set_move_score(self, mid, score):\n        entry = None\n        for e in self.moves:\n            if e[\'id\'] == mid:\n                entry = e\n                break\n        if entry is None:\n            return\n        entry[\'score\'] = score\n        if abs(score) >= 10000:\n            tag = \'red\' if score > 0 else \'black\'\n        elif score > 0:\n            tag = \'red\'\n        elif score < 0:\n            tag = \'black\'\n        else:\n            tag = \'zero\'\n        self.move_tree.item(str(mid),\n                            values=(entry[\'n\'], entry[\'notation\'], self._score_cell(score)),\n                            tags=(tag,))\n        self.update_status()\n\n    def check_game_state(self):\n        moves = legal_moves(self.board, self.turn)\n        self.last_check = is_in_check(self.board, self.turn)\n        if not moves:\n            winner = other(self.turn)\n            reason = \'将死\' if self.last_check else \'困毙\'\n            self.finish_game(winner, reason)\n            return\n        if self.mode == \'ai\' and self.turn != self.human_color:\n            self.start_ai()\n        elif self.auto_both:\n            # 自动解局: 步与步之间稍作停顿, 便于观看\n            self.root.after(600, self._auto_step)\n\n    def finish_game(self, winner, reason):\n        self.game_over = True\n        name = \'红方\' if winner == \'r\' else \'黑方\'\n        self.result_text = \'%s胜(%s)\' % (name, reason)\n        # 最后一步就是分出胜负的一步: 还没有分或只是普通分时, 补上胜负分\n        if self.moves:\n            last = self.moves[-1]\n            if last[\'score\'] is None or abs(last[\'score\']) < 10000:\n                self.set_move_score(last[\'id\'], MATE if winner == \'r\' else -MATE)\n        self.render()\n        messagebox.showinfo(\'对局结束\', self.result_text)\n\n    def undo(self):\n        if self.in_setup or not self.history:\n            return\n        self.view_idx = None\n        if self.auto_both:\n            self._stop_solving()   # 悔棋自动停止解局(含思考中的搜索)\n        if self.ai_thinking:\n            return\n        # history[k] 是"第 k+1 步走之前"的快照:\n        # 撤回哪一步, 就恢复到那一步被弹出时的快照(即它走之前的局面)\n        target = None\n        if self.mode == \'ai\':\n            # 撤回电脑的最后一步 + 自己的最后一步(回到自己上次走棋前)\n            if self.turn == self.human_color:\n                self.history.pop()\n                if self.history:\n                    target = self.history.pop()\n            else:\n                target = self.history.pop()\n        else:\n            target = self.history.pop()\n        while len(self.moves) > len(self.history):\n            self.move_tree.delete(str(self.moves[-1][\'id\']))\n            self.moves.pop()\n        self.score_gen += 1\n        self.cur_token += 1       # 旧搜索事件作废\n        self.engine.stop()\n        self.board = [list(row) for row in target] if target is not None \\\n            else [list(row) for row in self.start_snap]\n        self.turn = self.start_turn if len(self.history) % 2 == 0 else other(self.start_turn)\n        self.game_over = False\n        self.result_text = \'\'\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        self.last_move = self.moves[-1][\'mv\'] if self.moves else None\n        self._tree_guard = True\n        try:\n            if self.moves:\n                self.move_tree.selection_set(str(self.moves[-1][\'id\']))\n        finally:\n            self._tree_guard = False\n        self.render()\n        if self.mode == \'ai\' and self.turn != self.human_color:\n            self.start_ai()\n\n    def hint(self):\n        if self.mode != \'ai\' or self.game_over or self.ai_thinking \\\n                or self.in_setup or self.view_idx is not None:\n            return\n        if self.auto_both or self.turn != self.human_color:\n            return\n        depth = min(int(self.depth_var.get()), 12)   # 提示限个深度, 保证几秒内出\n        if self.use_engine:\n            self.hint_pending = True\n            self._start_analysis(None, depth)\n        else:\n            threading.Thread(target=self._hint_worker, args=(depth,), daemon=True).start()\n\n    def _hint_worker(self, depth):\n        mv, _ = search_depth(self.board, self.human_color, depth)\n        self.event_q.put((\'hint\', mv))\n\n    def _hint_done(self, mv):\n        self.hint_move = mv\n        self.render()\n\n    # ---------- 对局记录浏览与编辑 ----------\n    def _idx_of_iid(self, iid):\n        try:\n            mid = int(iid)\n        except (TypeError, ValueError):\n            return None\n        for k, e in enumerate(self.moves):\n            if e[\'id\'] == mid:\n                return k\n        return None\n\n    def browse_to(self, idx):\n        """显示第 idx 步之后的局面; None 或最后一步 = 当前局面"""\n        if idx is None or idx >= len(self.moves) - 1:\n            self._view_live()\n        else:\n            self._view_position(idx)\n\n    def _view_live(self):\n        if self.view_idx is None:\n            return\n        self.view_idx = None\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        self.render()\n\n    def _view_position(self, idx):\n        if not 0 <= idx < len(self.history):\n            self._view_live()\n            return\n        self.view_idx = idx\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        self.render()\n\n    def on_tree_click(self, event):\n        if self.in_setup:\n            return None\n        row = self.move_tree.identify_row(event.y)\n        if not row:\n            return None\n        idx = self._idx_of_iid(row)\n        if idx is None:\n            return None\n        self.move_tree.focus_set()\n        if idx == self.view_idx:\n            # 再点正在查看的行: 回到当前局面并取消选中\n            self._view_live()\n            self._tree_guard = True\n            try:\n                self.move_tree.selection_remove(row)\n            finally:\n                self._tree_guard = False\n            return \'break\'\n        if idx == len(self.moves) - 1:\n            self._view_live()      # 最后一行就是当前局面\n        return None                # 其余交给默认选中, 由 <<TreeviewSelect>> 浏览\n\n    def on_move_selected(self, _ev=None):\n        if self._tree_guard or self.in_setup:\n            return\n        sel = self.move_tree.selection()\n        self.browse_to(self._idx_of_iid(sel[0]) if sel else None)\n\n    def on_tree_right_click(self, event):\n        if self.in_setup:\n            return\n        row = self.move_tree.identify_row(event.y)\n        idx = self._idx_of_iid(row) if row else None\n        if idx is None:\n            return\n        self._tree_guard = True\n        try:\n            self.move_tree.selection_set(row)\n        finally:\n            self._tree_guard = False\n        self.browse_to(idx)\n        e = self.moves[idx]\n        after_n = len(self.moves) - idx - 1\n        menu = tk.Menu(self.root, tearoff=0)\n        menu.add_command(label=\'修改记谱「%s」...\' % e[\'notation\'],\n                         command=lambda: self.edit_notation(idx))\n        menu.add_separator()\n        if after_n:\n            menu.add_command(label=\'从此步继续对弈(删除其后%d步)\' % after_n,\n                             command=lambda: self.truncate_moves(idx + 1))\n        menu.add_command(label=\'退回此步之前(删除此步及其后%d步)\' % (after_n + 1),\n                         command=lambda: self.truncate_moves(idx))\n        try:\n            menu.tk_popup(event.x_root, event.y_root)\n        finally:\n            menu.grab_release()\n\n    def edit_notation(self, idx):\n        e = self.moves[idx]\n        ans = simpledialog.askstring(\'修改记谱\', \'第%d步记谱:\' % e[\'n\'],\n                                     initialvalue=e[\'notation\'], parent=self.root)\n        if ans is None:\n            return\n        ans = ans.strip()\n        if ans:\n            e[\'notation\'] = ans\n            self.move_tree.item(str(e[\'id\']),\n                                values=(e[\'n\'], ans, self._score_cell(e[\'score\'])))\n\n    def truncate_moves(self, keep):\n        """编辑记录: 只保留前 keep 步, 第 keep 步之后的局面成为当前对局局面"""\n        if self.in_setup:\n            return\n        keep = max(0, min(keep, len(self.moves)))\n        if keep == len(self.moves):\n            self._view_live()\n            return\n        self.score_gen += 1\n        self.cur_token += 1\n        self.engine.stop()\n        self.ai_thinking = False\n        self.hint_pending = False\n        if self.auto_both:\n            self.auto_both = False\n            self.btn_auto.config(text=\'自动解局\')\n        self.game_over = False\n        self.result_text = \'\'\n        kept = {str(e[\'id\']) for e in self.moves[:keep]}\n        for item in self.move_tree.get_children():\n            if item not in kept:\n                self.move_tree.delete(item)\n        # history[k] 是第 k 步走之前的快照: 保留前 keep 步后, 当前局面 = history[keep]\n        snap = self.history[keep]\n        self.moves = self.moves[:keep]\n        self.history = self.history[:keep]\n        self.view_idx = None\n        self.selected = None\n        self.legal = []\n        self.hint_move = None\n        if keep:\n            self.board = [list(row) for row in snap]\n            self.last_move = self.moves[-1][\'mv\']\n            mover = self.board[self.last_move[1][0]][self.last_move[1][1]]\n            self.turn = other(mover.color) if mover else self.start_turn\n        else:\n            self.board = [list(row) for row in self.start_snap]\n            self.last_move = None\n            self.turn = self.start_turn\n        self._tree_guard = True\n        try:\n            if self.moves:\n                self.move_tree.selection_set(str(self.moves[-1][\'id\']))\n                self.move_tree.see(str(self.moves[-1][\'id\']))\n        finally:\n            self._tree_guard = False\n        self.render()\n        self.check_game_state()\n\n    # ---------- 电脑走棋 ----------\n    def start_ai(self):\n        """轮到电脑: 用强引擎(或回退内置搜索)计算走法, 搜索同时给出当前局面分"""\n        self.ai_thinking = True\n        self.engine_depth = 0\n        mid = self.moves[-1][\'id\'] if self.moves else None\n        if self.use_engine:\n            self._start_analysis(mid)\n        else:\n            depth = min(int(self.depth_var.get()), 4)\n            threading.Thread(target=self._ai_worker,\n                             args=(self.game_id, depth), daemon=True).start()\n        self.update_status()\n\n    def _ai_worker(self, gid, depth):\n        mv, val = search_depth(self.board, self.turn, depth)\n        self.event_q.put((\'ai\', mv, val, gid))\n\n    def _ai_done(self, mv, val, gid):\n        if gid != self.game_id:\n            return\n        self.ai_thinking = False\n        if mv is None:\n            winner = other(self.turn)\n            self.finish_game(winner, \'将死\' if is_in_check(self.board, self.turn) else \'困毙\')\n        else:\n            # val 是电脑视角的分数, 换算成红方视角再显示\n            red_score = val * (1 if self.turn == \'r\' else -1)\n            # 电脑搜索的是"人走完之后"的局面: 这一步的分同时就是人上一步的分\n            if self.moves and self.moves[-1][\'score\'] is None:\n                self.set_move_score(self.moves[-1][\'id\'], red_score)\n            self.do_move(mv, score=red_score)\n\n    # ---------- 鼠标走棋 ----------\n    def on_click(self, event):\n        if self.in_setup:\n            cell = self.pixel_to_cell(event.x, event.y)\n            if cell is not None:\n                r, f = cell\n                self.setup_click(self.vr(r), self.vf(f), erase=(event.num == 3))\n            return\n        if self.view_idx is not None:\n            # 浏览记录时点棋盘 = 回到当前局面(此次点击不落子)\n            self._view_live()\n            sel = self.move_tree.selection()\n            if sel:\n                self._tree_guard = True\n                try:\n                    self.move_tree.selection_remove(sel)\n                finally:\n                    self._tree_guard = False\n            return\n        if getattr(event, \'num\', 1) != 1:\n            return\n        if self.game_over or self.ai_thinking or self.auto_both:\n            return\n        if self.mode == \'ai\' and self.turn != self.human_color:\n            return\n        cell = self.pixel_to_cell(event.x, event.y)\n        if cell is None:\n            return\n        r, f = cell\n        # 显示坐标 → 实际棋盘坐标(翻转显示时换算回来)\n        r = self.vr(r)\n        f = self.vf(f)\n        if self.selected is not None:\n            if (r, f) in self.legal:\n                self.do_move((self.selected, (r, f)))\n                return\n            p = self.board[r][f]\n            if p and p.color == self.turn:\n                self.selected = (r, f)\n                self.legal = [(tr, tf) for (fr, fc), (tr, tf)\n                              in legal_moves(self.board, self.turn) if (fr, fc) == (r, f)]\n                self.hint_move = None\n                self.render()\n                return\n            self.selected = None\n            self.legal = []\n            self.render()\n            return\n        p = self.board[r][f]\n        if p and p.color == self.turn:\n            self.selected = (r, f)\n            self.legal = [(tr, tf) for (fr, fc), (tr, tf)\n                          in legal_moves(self.board, self.turn) if (fr, fc) == (r, f)]\n            self.hint_move = None\n            self.render()\n\n    def pixel_to_cell(self, x, y):\n        f = round((x - MARGIN) / CELL)\n        r = round((y - MARGIN) / CELL)\n        if 0 <= f < COLS and 0 <= r < ROWS:\n            if abs(x - (MARGIN + f * CELL)) <= CELL / 2 and \\\n                    abs(y - (MARGIN + r * CELL)) <= CELL / 2:\n                return r, f\n        return None\n\n    # ---------- 绘制 ----------\n    def px(self, f):\n        return MARGIN + f * CELL\n\n    def py(self, r):\n        return MARGIN + r * CELL\n\n    def vr(self, r):\n        """实际行 → 显示行(上下翻转时上下对调; 反变换相同)"""\n        return 9 - r if self.flip_ud.get() else r\n\n    def vf(self, f):\n        """实际列 → 显示列(左右翻转时左右镜像; 反变换相同)"""\n        return 8 - f if self.flip_lr.get() else f\n\n    def render(self):\n        c = self.canvas\n        c.delete(\'all\')\n        self.draw_board()\n        if self.in_setup:\n            # 摆棋模式: 只画棋子与捡起标记\n            for r in range(ROWS):\n                for f in range(COLS):\n                    if self.board[r][f]:\n                        self.draw_piece(r, f, self.board[r][f])\n            if self.setup_pick:\n                r, f = self.setup_pick\n                x, y = self.px(self.vf(f)), self.py(self.vr(r))\n                c.create_rectangle(x - CELL / 2 + 2, y - CELL / 2 + 2,\n                                   x + CELL / 2 - 2, y + CELL / 2 - 2,\n                                   fill=\'#bcd8ef\', outline=\'\')\n            self.update_status()\n            return\n        # 浏览对局记录时显示该步之后的局面(history[k]是第k步走之前的快照)\n        if self.view_idx is not None:\n            i = self.view_idx\n            b = self.history[i + 1] if i + 1 < len(self.history) else self.board\n            last_mv = self.moves[i][\'mv\']\n            mover = b[last_mv[1][0]][last_mv[1][1]]\n            turn = other(mover.color) if mover else self.turn\n            chk = is_in_check(b, turn)\n        else:\n            b = self.board\n            last_mv = self.last_move\n            turn = self.turn\n            if not self.game_over:\n                self.last_check = is_in_check(self.board, self.turn)\n            chk = self.last_check\n        # 上一步走法标记(浏览历史局面时不显示)\n        if last_mv and self.view_idx is None:\n            for r, f in self.last_move:\n                x, y = self.px(self.vf(f)), self.py(self.vr(r))\n                c.create_rectangle(x - CELL / 2 + 2, y - CELL / 2 + 2,\n                                   x + CELL / 2 - 2, y + CELL / 2 - 2,\n                                   fill=\'#e6c96a\', outline=\'\')\n        # 提示走法\n        if self.hint_move:\n            (fr, fc), (tr, tc) = self.hint_move\n            for r, f in ((fr, fc), (tr, tc)):\n                x, y = self.px(self.vf(f)), self.py(self.vr(r))\n                c.create_rectangle(x - CELL / 2 + 2, y - CELL / 2 + 2,\n                                   x + CELL / 2 - 2, y + CELL / 2 - 2,\n                                   fill=\'#bcd8ef\', outline=\'\')\n        # 可走位置\n        for tr, tf in self.legal:\n            x, y = self.px(self.vf(tf)), self.py(self.vr(tr))\n            if self.board[tr][tf] is None:\n                c.create_oval(x - 7, y - 7, x + 7, y + 7, fill=\'#2e7d32\', outline=\'\')\n            else:\n                c.create_oval(x - PIECE_R - 3, y - PIECE_R - 3,\n                              x + PIECE_R + 3, y + PIECE_R + 3,\n                              outline=\'#2e7d32\', width=3)\n        # 棋子\n        for r in range(ROWS):\n            for f in range(COLS):\n                p = b[r][f]\n                if p:\n                    self.draw_piece(r, f, p)\n        # 被将军提示(红圈)\n        if chk and (self.view_idx is not None or not self.game_over):\n            k = find_king(b, turn)\n            if k:\n                x, y = self.px(self.vf(k[1])), self.py(self.vr(k[0]))\n                c.create_oval(x - PIECE_R - 5, y - PIECE_R - 5,\n                              x + PIECE_R + 5, y + PIECE_R + 5,\n                              outline=\'#e53935\', width=3)\n        self.update_status()\n\n    def draw_board(self):\n        c = self.canvas\n        for f in range(COLS):\n            x = self.px(f)\n            if f in (0, 8):\n                c.create_line(x, self.py(0), x, self.py(9), fill=LINE)\n            else:\n                c.create_line(x, self.py(0), x, self.py(4), fill=LINE)\n                c.create_line(x, self.py(5), x, self.py(9), fill=LINE)\n        for r in range(ROWS):\n            c.create_line(self.px(0), self.py(r), self.px(8), self.py(r), fill=LINE)\n        # 九宫斜线\n        c.create_line(self.px(3), self.py(0), self.px(5), self.py(2), fill=LINE)\n        c.create_line(self.px(5), self.py(0), self.px(3), self.py(2), fill=LINE)\n        c.create_line(self.px(3), self.py(7), self.px(5), self.py(9), fill=LINE)\n        c.create_line(self.px(5), self.py(7), self.px(3), self.py(9), fill=LINE)\n        # 楚河汉界(随左右翻转镜像)\n        river_font = (\'Microsoft YaHei\', 15)\n        c.create_text((self.px(self.vf(1)) + self.px(self.vf(3))) / 2, self.py(4.5),\n                      text=\'楚  河\', font=river_font, fill=LINE)\n        c.create_text((self.px(self.vf(5)) + self.px(self.vf(7))) / 2, self.py(4.5),\n                      text=\'漢  界\', font=river_font, fill=LINE)\n        # 炮位/兵位角标\n        marks = [(2, 1), (2, 7), (7, 1), (7, 7)]\n        marks += [(3, f) for f in (0, 2, 4, 6, 8)]\n        marks += [(6, f) for f in (0, 2, 4, 6, 8)]\n        for r, f in marks:\n            x, y = self.px(f), self.py(r)\n            d = 7\n            for dx, dy in ((-1, -1), (1, -1), (-1, 1), (1, 1)):\n                c.create_line(x + dx * d, y + dy * d, x + dx * (d - 4), y + dy * d, fill=LINE)\n                c.create_line(x + dx * d, y + dy * d, x + dx * d, y + dy * (d - 4), fill=LINE)\n\n    def draw_piece(self, r, f, p):\n        x, y = self.px(self.vf(f)), self.py(self.vr(r))\n        selected = (self.selected == (r, f))\n        outline = \'#c62828\' if selected else \'#7a4a21\'\n        width = 3 if selected else 2\n        c = self.canvas\n        c.create_oval(x - PIECE_R, y - PIECE_R, x + PIECE_R, y + PIECE_R,\n                      fill=\'#f8e3b0\', outline=outline, width=width)\n        color = \'#c62828\' if p.color == \'r\' else \'#1a1a1a\'\n        c.create_text(x, y, text=char_of(p), fill=color, font=PIECE_FONT)\n\n    @staticmethod\n    def _score_cell(score):\n        """对局记录"局面分"列的显示文字"""\n        if score is None:\n            return \'…\'\n        if abs(score) >= 10000:\n            n = (MATE - abs(score)) // 100   # 引擎绝杀分: 距终局的回合数\n            base = \'红胜\' if score > 0 else \'黑胜\'\n            return base if n < 1 else \'%s(%d回合内)\' % (base, n)\n        if score > 0:\n            return \'%+d\' % score\n        if score < 0:\n            return \'%+d\' % score\n        return \'0\'\n\n    @staticmethod\n    def score_text(v):\n        if abs(v) >= 10000:\n            n = (MATE - abs(v)) // 100   # 引擎绝杀分: 距终局的回合数\n            base = \'红胜\' if v > 0 else \'黑胜\'\n            return base if n < 1 else \'%s(%d回合内)\' % (base, n)\n        if v > 0:\n            return \'红优 +%d\' % v\n        if v < 0:\n            return \'黑优 +%d\' % -v\n        return \'均势\'\n\n    def update_status(self):\n        if self.in_setup:\n            self.status.config(text=\'摆棋模式: 选棋子放置 / 右键删除 / 不选工具点棋子移动; \'\n                                    \'摆好后点"完成摆棋"\', fg=\'#6a4a12\')\n            return\n        if self.view_idx is not None:\n            e = self.moves[self.view_idx]\n            text = \'查看第%d步 %s\' % (e[\'n\'], e[\'notation\'])\n            if e[\'score\'] is not None:\n                text += \' | 局面: %s\' % self.score_text(e[\'score\'])\n            text += \'(再点该行/最后一行或点棋盘返回)\'\n            self.status.config(text=text, fg=\'#1565c0\')\n            return\n        if self.game_over:\n            self.status.config(text=self.result_text, fg=\'#c62828\')\n        elif self.auto_both and not self.ai_thinking:\n            self.status.config(text=\'自动解局进行中...\', fg=\'#1565c0\')\n        elif self.ai_thinking:\n            prefix = \'自动解局: \' if self.auto_both else \'\'\n            if self.use_engine and self.engine_target:\n                self.status.config(text=\'%s电脑思考中... (深度 %d/%d)\'\n                                   % (prefix, self.engine_depth, self.engine_target), fg=\'#1565c0\')\n            else:\n                self.status.config(text=\'%s电脑思考中...\' % prefix, fg=\'#1565c0\')\n        else:\n            name = \'红方\' if self.turn == \'r\' else \'黑方\'\n            text = \'%s走棋\' % name\n            if self.mode == \'ai\':\n                text += \'(你执%s)\' % (\'红\' if self.human_color == \'r\' else \'黑\')\n            if self.last_check:\n                text = \'将军! \' + text\n            if self.moves and self.moves[-1][\'score\'] is not None:\n                text += \' | 局面: %s\' % self.score_text(self.moves[-1][\'score\'])\n            self.status.config(text=text, fg=\'#333\')\n\n\ndef main():\n    try:\n        import ctypes\n        ctypes.windll.shcore.SetProcessDpiAwareness(1)\n    except Exception:\n        pass\n    root = tk.Tk()\n    XiangqiApp(root)\n    root.mainloop()\n\n\nif __name__ == \'__main__\':\n    try:\n        main()\n    except Exception:\n        import traceback\n        tb = traceback.format_exc()\n        import os\n        try:\n            with open(os.path.join(os.path.dirname(os.path.abspath(__file__)),\n                                   \'xiangqi_error.log\'), \'a\', encoding=\'utf-8\') as f:\n                f.write(tb)\n        except Exception:\n            pass\n        try:\n            messagebox.showerror(\'中国象棋\', tb)\n        except Exception:\n            pass\n'

FONT = None
for _c in ("NotoSansCJK-Regular.ttf", "NotoSansSC-Regular.ttf", "msyh.ttf", "simhei.ttf"):
    if os.path.exists(_c):
        FONT = _c
        break

APP_DIR = os.path.dirname(os.path.abspath(__file__))

def _persistent_dir():
    """应用专属的可读写数据目录（重启、升级 APP 都保留）"""
    d = None
    try:
        from jnius import autoclass
        d = autoclass("org.kivy.android.PythonActivity").mActivity.getFilesDir().getAbsolutePath()
    except Exception:
        d = None
    if not d:
        d = APP_DIR
    sub = os.path.join(d, "userdata")
    try:
        os.makedirs(sub, exist_ok=True)
    except Exception:
        sub = APP_DIR
    return sub

DATA_DIR = _persistent_dir()

# 首次运行：把 APK 内置的初始数据文件复制为可读写副本（已存在的不覆盖，
# 因此脚本每次运行写入的最新内容都会保留）
try:
    for _f in os.listdir(APP_DIR):
        _s = os.path.join(APP_DIR, _f)
        _t = os.path.join(DATA_DIR, _f)
        if os.path.isfile(_s) and _f != "main.py" and not os.path.exists(_t):
            shutil.copyfile(_s, _t)
except Exception:
    pass

# 让脚本里的相对路径（如 open("xx.json")）自动落在持久化数据目录
try:
    os.chdir(DATA_DIR)
except Exception:
    pass

_out_q = queue.Queue()

class _Out(io.TextIOBase):
    def write(self, s):
        if s:
            _out_q.put(s)
        return len(s)
    def flush(self):
        pass

class RunnerApp(App):
    def build(self):
        Window.clearcolor = (0.91, 0.96, 0.91, 1)
        self._running = False
        self._started = False
        root = BoxLayout(orientation="vertical", padding=12, spacing=10)
        self.btn = Button(text="▶ 运行脚本", size_hint_y=None, height=54,
                          background_normal="", background_color=(0.26, 0.63, 0.28, 1),
                          color=(1, 1, 1, 1), bold=True,
                          font_name=FONT or "Roboto", font_size="17sp")
        self.btn.bind(on_press=self.on_run)
        self.label = Label(halign="left", valign="top",
                           color=(0.06, 0.22, 0.09, 1),
                           font_name=FONT or "Roboto", font_size="13sp",
                           size_hint_y=None)
        self.label.bind(width=lambda _i, w: setattr(_i, "text_size", (w, None)))
        self.label.bind(texture_size=lambda _i, s: setattr(_i, "height", max(s[1], 20)))
        sv = ScrollView()
        sv.add_widget(self.label)
        root.add_widget(self.btn)
        root.add_widget(sv)
        Clock.schedule_interval(self.poll, 0.15)
        return root

    def poll(self, dt):
        chunk = []
        try:
            while True:
                chunk.append(_out_q.get_nowait())
        except queue.Empty:
            pass
        if chunk:
            self.label.text += "".join(chunk)
        if self._started and not self._running:
            self._started = False
            self.btn.disabled = False

    def on_run(self, *_a):
        if self._running:
            return
        self.btn.disabled = True
        self.label.text += "\n──── 运行脚本 ────\n"
        self._running = True
        self._started = True

        def work():
            g = {"__name__": "__main__", "__file__": os.path.abspath(__file__)}
            try:
                with contextlib.redirect_stdout(_Out()), contextlib.redirect_stderr(_Out()):
                    exec(USER_CODE, g)
                _out_q.put("\n──── 运行结束 ────\n")
            except Exception:
                _out_q.put("\n──── 脚本出错 ────\n" + traceback.format_exc())
            finally:
                self._running = False

        threading.Thread(target=work, daemon=True).start()

RunnerApp().run()
